from pathlib import Path
import json
import re

ROOT = Path(__file__).parent
DATA = {
    'brand': '家常账', 'person': '林然', 'title': '个人日常',
    'date': '10 月 14 日，星期三', 'month': '2026 年 10 月',
    'amount': '3,487.90', 'basis': '本人支付，含家庭费用。支出已扣除退款。',
    'privacy': '个人待办只提醒自己。',
    'actions': ['记一笔', '拍票据', '新建待办'],
    'descriptions': ['记录日常消费', '识别后核对保存', '提醒自己的小事'],
    'tasks': [
        {'title': '个人会员订阅', 'date': '10 月 15 日到期', 'type': '费用待支付', 'action': '去支付', 'icon': 'clock'},
        {'title': '预约牙齿检查', 'date': '10 月 15 日到期', 'type': '待办任务', 'action': '查看', 'icon': 'tasks'},
    ],
}
(ROOT / 'content.json').write_text(json.dumps(DATA, ensure_ascii=False, indent=2), encoding='utf-8')
paths = {
 'home':'<path d="m3 10 9-7 9 7v10H4V10M9 21v-8h6v8"/>',
 'book':'<path d="M12 5v16M3 4h6l3 2 3-2h6v16h-6l-3 2-3-2H3Z"/>',
 'tasks':'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m7 9 2 2 3-3M14 9h3M7 16h10"/>',
 'chart':'<path d="M4 3v17h17M8 15v-4M13 15V6M18 15v-7"/>',
 'user':'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
 'camera':'<path d="M8 5 9 3h6l1 2h4v16H3V5Z"/><circle cx="12" cy="12" r="4"/>',
 'plus':'<path d="M12 4v16M4 12h16"/>',
 'clock':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 'bell':'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4"/>',
 'arrow':'<path d="M4 12h16m-6-6 6 6-6 6"/>',
}
def icon(name):
 return '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name]+'</svg>'
nav = [('home','首页'), ('book','账本'), ('tasks','待办与提醒'), ('chart','报表'), ('user','我的')]
def navigation():
 return ''.join(f'<span class="nav-item {"active" if i==0 else ""}">{icon(k)}{v}</span>' for i,(k,v) in enumerate(nav))
def actions():
 return ''.join(f'<div class="action action-{i}"><span class="action-icon">{icon(k)}</span><strong>{label}</strong><small>{DATA["descriptions"][i]}</small><span class="action-arrow">↗</span></div>' for i,(label,k) in enumerate(zip(DATA['actions'],['plus','camera','tasks'])))
def taskrows():
 return ''.join(f'<div class="task"><span class="task-icon">{icon(t["icon"])}</span><div class="task-copy"><strong>{t["title"]}</strong><small>{t["date"]} · {t["type"]}</small></div><span class="task-button">{t["action"]} →</span></div>' for t in DATA['tasks'])
base = '''*{box-sizing:border-box}body{margin:0;font-family:"Segoe UI","Microsoft YaHei",sans-serif;font-size:15px;line-height:1.6}h1,h2,p{margin:0}h1{font-size:30px;line-height:1.3;letter-spacing:-1px}h2{font-size:20px;font-weight:600}small{font-size:13px;line-height:1.6}svg{flex-shrink:0}strong{font-weight:600}.nav-item{display:flex;align-items:center;gap:13px}.brand{font-size:23px;font-weight:700;display:flex;align-items:center;gap:12px}.brandmark{display:grid;place-items:center;width:38px;height:38px;font-size:20px}.space{display:inline-flex;align-items:center;gap:3px;padding:4px;border-radius:9px}.space span{padding:6px 23px}.avatar{width:36px;height:36px;display:grid;place-items:center;border-radius:50%}.amount{font-variant-numeric:tabular-nums;line-height:1.08;letter-spacing:-4px}.currency{font-size:27px;letter-spacing:0;margin-right:10px}.muted{color:var(--muted)}.section-head{display:flex;align-items:center;justify-content:space-between}.link{font-size:14px}.task{display:flex;align-items:center;gap:17px}.task-copy{flex:1}.task-copy strong,.task-copy small{display:block}.task-copy small{margin-top:6px;color:var(--muted)}.task-button{font-size:14px;white-space:nowrap}.action{position:relative}.action strong,.action small{display:block}.action small{margin-top:6px}.action-icon{display:block}.action-arrow{position:absolute;font-size:23px}.foot{font-size:13px;display:flex;justify-content:space-between}'''
def save(name, css, body):
 body = body.replace('{{NAV}}',navigation()).replace('{{ACTIONS}}',actions()).replace('{{TASKS}}',taskrows())
 for k,v in DATA.items():
  if isinstance(v,str):body=body.replace('{{'+k+'}}',v)
 for k in paths:body=body.replace('{{ICON:'+k+'}}',icon(k))
 if name == 'b-calendar': css += '.summary small{color:#70565c}'
 if name == 'c-ledger': css += '.action-0{background:#b63816}.action-0 small{color:#ffffff}'
 (ROOT / (name+'.html')).write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>家常账 · '+name+'</title><style>'+base+css+'</style></head><body>'+body+'</body></html>', encoding='utf-8')

